#!/usr/bin/env python3
"""Apply recorded local edits to the original independent English, preserving all 56 blocks."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];M=R/'data/we-three/multilingual';source=json.loads((M/'source-original.json').read_text())['articles'];changes={}
def edit(e,n,old,new,why):
 before=source[e-1]['body_en'][n-1];text=changes.get((e,n),{}).get('after',before);assert old in text,(e,n,old)
 rec=changes.setdefault((e,n),{'article':e,'source_block':n,'before':before,'after':text,'reasons':[]});rec['after']=text.replace(old,new);rec['reasons'].append(why)
edit(1,2,'an inn admits her for one night only; questions are useless;','she follows visible paths, does not ask about what she does not know, and returns to an inn by sunset;','Dream rules do not limit each inn to one night.')
edit(1,4,'The next year Qian Yuan, their only daughter, was admitted to another hospital.','Qian Yuan, their only daughter, fell ill at the end of 1995 and entered another hospital early in 1996.','Author chronology distinguishes onset from admission.')
edit(1,4,'The inn that never permits a second night captures the absence of any place where the carer may finally stop.','The changing inns along the journey capture the absence of any place where the carer may finally settle.','Remove invented one-night rule; retain author interpretation.')
edit(1,8,'They moved repeatedly and owned none of these places in the ordinary sense. Their home therefore could never be identified securely with property.','They moved repeatedly during their shared life. The continuity of home lay not in any one building but in the people living together.','Do not claim lifelong absence of property; preserve home-as-people argument.')
edit(1,8,'“Inn” is both literal and existential. Buildings sheltered them temporarily.','“Inn” draws force from those repeated moves as well as from the dream. Buildings sheltered them at different stages.','No unsupported literal-property proof.')
edit(1,10,'“The Two of Us Grow Old.”','“The Two of Us Have Both Grown Old.”','Full Chinese first-part title includes 都.')
edit(2,1,'Breakfast for a lifetime','Breakfast across the years','Avoid suggestion of an uninterrupted daily rule.')
edit(2,2,'In Oxford in 1935,','In their early Oxford days,','Breakfast occurs around New Year; no need to fix it to 1935.')
edit(2,2,'carried upstairs on a large tray.','carried to her bed on a large tray.','No unsupported downstairs/upstairs route.')
edit(2,2,'Zhongshu made breakfast through Oxford, the return to China, Shanghai, Beijing and the decades that followed, until illness stopped him in his eighties.','Zhongshu regularly made breakfast through Oxford, the return to China, Shanghai, Beijing and the decades that followed. Yang specifies exceptions: periods in an extended-family household, periods when a maid prepared their meals, and his illnesses.','Book explicitly states three exceptions; preserve long habit.')
edit(2,2,'Repeated for a lifetime,','Repeated across decades,','Same continuity qualification.')
edit(2,6,'She woke protesting, and he did it again.','His mother scolded him, and he did not dare repeat it.','Original prank is one summer incident, not recurring after daughter protests.')
edit(2,6,'As an adult she traded teasing notes with him. Because she lived at some distance, one would leave a scrap on the table, the other answer, and the exchange continue with reports of foolish behaviour and affectionate mockery. They kept the stacks.','As an adult she remained a companion in teasing. Family letters and remembered jokes preserve reports of foolish behaviour and affectionate mockery, small traces of their daily life.','Remove unverified distant-residence/table-relay/stacks combination without replacing private-language argument.')
edit(2,8,'learning Spanish in middle age','learning Spanish in her forties','Author chronology: 1958 at 47; align precise Chinese correction.')
edit(3,1,'A wig, a vegetable plot, a borrowed office','A wig, a vegetable plot, a borrowed office','Unverified garden vignette is not represented as this book’s scene.')
edit(3,2,'When Yang Jiang reaches 1966, she records that both she and Qian Zhongshu were subjected to the humiliating half-shaved hairstyle of the period. Her practical response was to recover hair cut from earlier years, combine it with some of her own and make a wig she could wear to buy groceries. When Zhongshu was sent to a cadre school in Henan and Yang followed, she writes about cultivating vegetables and the walks they could take when their assignments brought them within reach.','In her separate memoir Bingwu Dingwei Nian Jishi, Yang Jiang records their humiliation in 1966. A cross was shaved into Qian Zhongshu’s hair, and she later shaved the rest clean; she herself was subjected to a half-shaved head. Her practical response was to make a wig from her daughter’s saved braid, using her husband’s hair cap as its base and a small pot as a form. We Three recalls Zhongshu going to a cadre school in Henan and Yang following the next year. In the separate Six Chapters from My Life Downunder, she writes about the vegetable garden and their brief encounters there, keeping attention on daily work and ways of meeting.','Correct haircut subjects/materials and explicitly identify other memoir; do not invent this book’s garden vignette.')
edit(3,2,'After returning, they lacked housing and stayed in an office; later they moved books yet again.','After returning to Beijing they moved several more times, temporarily staying in an office in 1974; the books moved with them.','Do not collapse the later office stay into immediate post-cadre-school homelessness.')
edit(3,2,'The wig can sound ingenious, the vegetables become specific, and the catastrophe is not granted a rhetorical climax.','The wig can sound ingenious, the practical details remain specific, and the catastrophe is not granted a rhetorical climax.','Keep tone analysis after removing unverified vegetable details.')
edit(3,6,'Yang does not hide the shaved heads, denunciations, false accusations, banishment, lost work or absence of a home.','Yang does not hide suffering. We Three records denunciations, false accusations, banishment, interrupted work and insecure accommodation; the separate memoir supplies the detailed account of the shaved heads and wig.','Do not attribute every cross-text detail to We Three.')
edit(3,8,'Yang uses the words anxiety and loneliness for the cadre-school period; she does not deny suffering. She then records that the couple met at the edge of the vegetable ground and continued talking.','A passage in Six Chapters from My Life Downunder makes the relation concrete. Zhongshu’s quarters were a little over ten minutes from Yang’s vegetable garden. Serving as a messenger to the post office, he would later often pass the plot. They sat briefly in the sun on the bank of the channel or stood talking; he handed her letters written in fragments. Anxiety and loneliness are not erased, but the narrative continues with what they did within those conditions.','No unverified exact phrase or garden dialogue attributed to this book; preserve conjunction and proportion analysis.')
edit(3,12,'Yang notes that Zhongshu declined opportunities for advancement and continued pursuing recondite textual work whose utility to the moment was nearly impossible to state.','Yang notes that Zhongshu declined some appointments but also reluctantly accepted a nominal post: after resigning as an adviser to the Institute of Literature in 1982, he became a vice-president of the Chinese Academy of Social Sciences. His resignation a year later was not accepted; he continued to draw a researcher’s salary and kept reading and research at the centre of his life. His recondite textual work scarcely answered the demands of immediate utility.','Not a lifelong refusal of all office; retain noninstrumental reading without false premise.')
edit(4,1,'Eighteen years after two deaths','Nearly eighteen years after two deaths','Approximate duration rather than exact eighteen years.')
edit(4,2,'Qian Zhongshu less than a year later.','Qian Zhongshu a little over a year and nine months later, at the end of 1998.','Author chronology March1997/December1998.')
edit(4,2,'another eighteen years','nearly another eighteen years','Duration approximation.')
edit(4,2,'five years into that solitude.','several years into that solitude.','2002 completion and 2003 publication, not exactly five years after both deaths.')
edit(4,4,'had just lost husband and daughter','had lost husband and daughter','Writing was several years after bereavements.')
edit(4,6,'Oxford rooms were rented, Shanghai quarters borrowed, Beijing accommodation institutional and Sanlihe assigned. No building possessed an uninterrupted claim to be theirs.','During their shared life they moved repeatedly, from Oxford to Shanghai and Beijing, from temporary rooms to Sanlihe. The addresses changed; continuity was made by the people.','Avoid universal property claim; preserve narrow home relation point.')
edit(4,8,'The title is not My Husband and Daughter,','The third part is titled “I Alone Remember We Three”: in its nine Chinese characters, “I alone” names the present, “we three” the shared decades, and “remember with longing” joins them. The book’s title is not My Husband and Daughter,','Restore local nine-character close reading without restructuring or translating whole essay.')
edit(4,14,'captures two years during which','captures years during which','Hospital and loss chronology spans several years.')
arts=[];titles=['A Dream Ten Thousand Li Long','Things That Were of No Use','That Quiet Restraint','I Alone Remember We Three'];decks=['A dream follows the daily route of care and loss.','Breakfast, private jokes and three independent lives within one home.','Quiet narration gives history a place without surrendering the whole of memory.','A solitary writer remembers a shared life whose completed acts remain real.']
for i,a in enumerate(source):
 body=[changes.get((i+1,j+1),{}).get('after',x) for j,x in enumerate(a['body_en'])];assert len(body)==len(a['body_en'])==14;assert [j for j,x in enumerate(body) if x.startswith('## ')]==[j for j,x in enumerate(a['body_en']) if x.startswith('## ')]
 arts.append({'slug':a['slug'],'title':titles[i],'deck':decks[i],'body':body,'edition_note':'An independently structured English essay, retained with local factual corrections and a small restored close reading. It is not a block-by-block translation of the Chinese. Full-book spoilers.','coverage':'Retained independent English: 14 original blocks, 14 current blocks; original sequence and principal argument preserved, local edits recorded separately.'})
(M/'en.json').write_text(json.dumps({'language':'en','series':{'title':'Reading We Three','deck':'Four essays on care, unproductive joys, the proportions of memory and a home made by people.','intro':[],'note':'Yang Jiang, We Three (2003). English retains its independently structured essays with documented local corrections.'},'ui':{'series':'Reading We Three'},'articles':arts},ensure_ascii=False,indent=2)+'\n')
(M.parent/'english-corrections.json').write_text(json.dumps({'method':'Retain all four original independent English essays and their 14-block structures. Local factual corrections, necessary source-attribution qualifications, and one restored title close reading; no wholesale retranslation or Chinese-English block equality requirement.','corrections':[c for c in changes.values() if c['before']!=c['after']]},ensure_ascii=False,indent=2)+'\n')
print('Retained 56 English blocks; locally revised',sum(c['before']!=c['after'] for c in changes.values()),'blocks.')
